public class CareerFact {private Long id,profileId;private String factType,factKey,valueType,textValue,unit,displayName,source;private Boolean booleanValue;private Double numberValue;private LocalDateTime confirmedAt,createdAt,updatedAt;public Long getId(){return id;}public void setId(Long v){id=v;}public Long getProfileId(){return profileId;}public void setProfileId(Long v){profileId=v;}public String getFactType(){return factType;}public void setFactType(String v){factType=v;}public String getFactKey(){return factKey;}public void setFactKey(String v){factKey=v;}public String getValueType(){return valueType;}public void setValueType(String v){valueType=v;}public Boolean getBooleanValue(){return booleanValue;}public void setBooleanValue(Boolean v){booleanValue=v;}public Double getNumberValue(){return numberValue;}public void setNumberValue(Double v){numberValue=v;}public String getTextValue(){return textValue;}public void setTextValue(String v){textValue=v;}public String getUnit(){return unit;}public void setUnit(String v){unit=v;}public String getDisplayName(){return displayName;}public void setDisplayName(String v){displayName=v;}public String getSource(){return source;}public void setSource(String v){source=v;}public LocalDateTime getConfirmedAt(){return confirmedAt;}public void setConfirmedAt(LocalDateTime v){confirmedAt=v;}public LocalDateTime getCreatedAt(){return createdAt;}public void setCreatedAt(LocalDateTime v){createdAt=v;}public LocalDateTime getUpdatedAt(){return updatedAt;}public void setUpdatedAt(LocalDateTime v){updatedAt=v;}}
